import {
  MeterRoot,
  MeterLabel,
  MeterTrack,
  MeterRange,
  MeterValueText,
} from '@uifn/components-react/meter'
import '@uifn/components/styles.css'

export function Example() {
  return (
    <MeterRoot value={72} aria-label="Meter example">
      <MeterLabel>Storage used</MeterLabel>
      <MeterTrack>
        <MeterRange />
      </MeterTrack>
      <MeterValueText>64%</MeterValueText>
    </MeterRoot>
  )
}

import {
  SwitchRoot,
  SwitchControl,
  SwitchThumb,
  SwitchLabel,
  SwitchHiddenInput,
} from '@uifn/components-react/switch'
import '@uifn/components/styles.css'

export function Example() {
  return (
    <SwitchRoot defaultChecked name="darkMode">
      <SwitchControl type="button">
        <SwitchThumb />
      </SwitchControl>
      <SwitchLabel>Automatic updates</SwitchLabel>
      <SwitchHiddenInput />
    </SwitchRoot>
  )
}
